import React, { useEffect, useState } from "react";
import axios from "axios";
import { Doughnut } from "react-chartjs-2";
import { io } from "socket.io-client";
import "./App.css";

function App() {
  const [nodes, setNodes] = useState({});
  const [cpuCores, setCpuCores] = useState(1);
  const [socket, setSocket] = useState(null);

  useEffect(() => {
    // Initial API fetch
    fetchNodes();

    // Setup WebSocket
    const s = io(process.env.REACT_APP_API_URL);
    setSocket(s);

    s.on("node_update", (data) => setNodes(data));
    s.on("heartbeat", (data) => {
      console.log(`Heartbeat from ${data.node_id}`);
    });

    return () => s.disconnect();
  }, []);

  const fetchNodes = () => {
    axios.get(`${process.env.REACT_APP_API_URL}/api/nodes`).then((res) => {
      setNodes(res.data);
    });
  };

  const handleAddNode = (e) => {
    e.preventDefault();
    axios
      .post(`${process.env.REACT_APP_API_URL}/api/nodes`, {
        cpu_cores: cpuCores,
      })
      .then((res) => {
        alert("Node added: " + res.data.node_id);
        setCpuCores(1);
      })
      .catch((err) => {
        alert("Failed to add node.");
        console.error(err);
      });
  };

  const handleDeleteNode = (id) => {
    if (window.confirm("Delete node?")) {
      axios
        .delete(`${process.env.REACT_APP_API_URL}/api/nodes/${id}`)
        .then((res) => {
          alert(res.data.message);
        });
    }
  };

  const chartData = {
    labels: ["Used CPU", "Available CPU"],
    datasets: [
      {
        data: calculateCPU(nodes),
        backgroundColor: ["#ff6384", "#36a2eb"],
      },
    ],
  };

  function calculateCPU(nodes) {
    let used = 0,
      available = 0;
    Object.values(nodes).forEach((n) => {
      used += n.cpu - n.available_cpu;
      available += n.available_cpu;
    });
    return [used, available];
  }

  return (
    <div className="container">
      <h1>Cluster Dashboard</h1>

      <form onSubmit={handleAddNode}>
        <input
          type="number"
          min="1"
          value={cpuCores}
          onChange={(e) => setCpuCores(parseInt(e.target.value))}
          required
        />
        <button type="submit">Add Node</button>
      </form>

      <div style={{ maxWidth: "400px", margin: "20px auto" }}>
        <Doughnut data={chartData} />
      </div>

      <h2>Total Nodes: {Object.keys(nodes).length}</h2>

      <table>
        <thead>
          <tr>
            <th>ID</th>
            <th>Status</th>
            <th>CPU</th>
            <th>Available</th>
            <th>Pods</th>
            <th>Heartbeat</th>
            <th>Delete</th>
          </tr>
        </thead>
        <tbody>
          {Object.entries(nodes).map(([id, n]) => (
            <tr key={id}>
              <td>{id.slice(0, 8)}...</td>
              <td>{n.status}</td>
              <td>{n.cpu}</td>
              <td>{n.available_cpu}</td>
              <td>{n.pods.length}</td>
              <td>{n.last_heartbeat.toFixed(2)}</td>
              <td>
                <button onClick={() => handleDeleteNode(id)}>🗑️</button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

export default App;
